<?php
declare(strict_types=1);

namespace MageOS\DigitalSignature\Model\Dossier;

use Magento\Framework\App\Filesystem\DirectoryList;
use Magento\Framework\Filesystem;
use Magento\Framework\Filesystem\Directory\WriteInterface;
use Magento\Framework\Math\Random;

/**
 * Where dossier ZIPs live: var/digitalsignature/dossiers. Paths handled here
 * are relative to var/ and always generated by this class, never taken from
 * user input. Files are only ever served through ACL-checked controllers.
 */
class DossierFileLocator
{
    public const RELATIVE_DIR = 'digitalsignature/dossiers';
    private const TEMPORARY_PREFIX = 'tmp-';

    public function __construct(
        private readonly Filesystem $filesystem,
        private readonly Random $random
    ) {
    }

    public function newRelativePath(string $prefix): string
    {
        $this->varDir()->create(self::RELATIVE_DIR);
        $suffix = $this->random->getRandomString(16, Random::CHARS_LOWERS . Random::CHARS_DIGITS);

        return self::RELATIVE_DIR . '/' . $prefix . '-' . $suffix . '.zip';
    }

    public function absolutePath(string $relativePath): string
    {
        return (string)$this->varDir()->getAbsolutePath($relativePath);
    }

    public function exists(string $relativePath): bool
    {
        return (bool)$this->varDir()->isExist($relativePath);
    }

    public function size(string $relativePath): int
    {
        return (int)($this->varDir()->stat($relativePath)['size'] ?? 0);
    }

    /**
     * @throws \Magento\Framework\Exception\FileSystemException when the file exists but cannot be deleted
     */
    public function delete(string $relativePath): void
    {
        if ($this->varDir()->isExist($relativePath)) {
            $this->varDir()->delete($relativePath);
        }
    }

    /**
     * Synchronous exports are streamed and removed by the response; a request
     * killed mid-way leaves its tmp- file behind, which this removes. Also
     * removes what ZipArchive::close() leaves when the process is killed while
     * writing: it writes to "<archive>.XXXXXX" and renames it, so the leftover
     * never ends in .zip and no export row points to it.
     */
    public function deleteTemporaryFilesOlderThan(int $timestamp): int
    {
        $dir = $this->varDir();
        if (!$dir->isExist(self::RELATIVE_DIR)) {
            return 0;
        }

        $deleted = 0;
        foreach ($dir->read(self::RELATIVE_DIR) as $path) {
            $name = basename((string)$path);
            if (!str_starts_with($name, self::TEMPORARY_PREFIX) && str_ends_with($name, '.zip')) {
                continue;
            }
            if (!$dir->isFile($path)) {
                continue; // delete() is recursive on a directory
            }
            if ((int)($dir->stat($path)['mtime'] ?? PHP_INT_MAX) < $timestamp) {
                $dir->delete($path);
                $deleted++;
            }
        }

        return $deleted;
    }

    private function varDir(): WriteInterface
    {
        return $this->filesystem->getDirectoryWrite(DirectoryList::VAR_DIR);
    }
}
